import{_ as a,o as t,c as n,ag as o}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"ContainerEndpoint — takoform_container_endpoint","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/container/container-endpoint.md","filePath":"proposals/container/container-endpoint.md"}'),r={name:"proposals/container/container-endpoint.md"};function i(s,e,d,h,c,l){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="containerendpoint-—-takoform-container-endpoint" tabindex="-1">ContainerEndpoint — <code>takoform_container_endpoint</code> <a class="header-anchor" href="#containerendpoint-—-takoform-container-endpoint" aria-label="Permalink to &quot;ContainerEndpoint — `takoform_container_endpoint`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A team wants their service reachable, now, and does not yet own a domain — or owns one and does not want the first request to wait on delegation and verification. External clients reach the service&#39;s active traffic split over HTTPS at an address the host assigns and publishes; TLS termination and the naming scheme are the host&#39;s obligation, never portable state.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>attachment</code>. Inward activation is an attachment resource, never a binding (decision 0010). Deleting the attachment removes the address and never deletes the service.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>service</code> is the only desired member, and it is immutable: changing it replaces the attachment. Requests at the assigned address are delivered to instances of the revisions the service&#39;s ACTIVE TRAFFIC resource selects, so promotion and rollback move what answers without the endpoint being re-applied and without the address changing; each request is served entirely by one revision.</p><p>The address is published as outputs: <code>hostname</code> is the assigned DNS name, and <code>url</code> is exactly <code>https://</code> + that hostname + <code>/</code>. A portable author may rely on a value being returned, on the scheme being HTTPS, and on the address routing through the active traffic split — and on nothing about its shape: they must not parse it, assert a suffix, or reconstruct it from the resource name (<a href="./../../spec/decisions/0024-a-worker-is-reachable-at-a-host-assigned-address.html">decision 0024</a>, <a href="./../../spec/decisions/0025-declared-outputs-are-a-typed-contract.html">decision 0025</a>).</p><p>A service has at most one endpoint. A host that cannot assign an address refuses the attachment with <code>unsupported_capability</code> rather than answering with an address it did not assign.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Reachability without a name of one&#39;s own is one complete observable fact: the service answers at an address, over HTTPS, at the path root. Nothing about it is a variant of serving an author-owned hostname — the desired states are disjoint — so merging the two would need a selector token between two different requests.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>A name the author owns is <a href="./container-custom-domain.html">ContainerCustomDomain</a>. An address with a chosen label or a regional affinity would put host placement into desired state and is not a Form at all.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>The assigned address must be stable for the life of one incarnation: a consumer holding the URL must not find it moved by a traffic change it did not make. A second endpoint against one service must be refused deterministically, by the service&#39;s UID rather than its name. Attaching while the service has no traffic resource must be refused, per the family aggregate. Deleting the service while the endpoint exists must fail with <code>dependency_in_use</code>. Import must recover the service reference and the assigned address exactly, without minting a new one.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The host-assigned service URL of a proven serverless container platform, with the naming scheme kept host-side and the address published as contract rather than inferred.</p>',21)])])}const u=a(r,[["render",i]]);export{m as __pageData,u as default};
